<?php require __DIR__.'/config.php'; if ($_SERVER['REQUEST_METHOD']!=='POST' || !logged_in()) redirect('login.php'); verify_csrf(); $body=trim($_POST['body']??''); if($body==='') redirect('index.php?msg=نظر خالی است.'); $st=db()->prepare('SELECT username FROM users WHERE id=?'); $st->execute([$_SESSION['user_id']]); $u=$st->fetch(); if(!$u) redirect('login.php'); $st=db()->prepare('INSERT INTO comments(user_id,author_name,body) VALUES(?,?,?)'); $st->execute([$_SESSION['user_id'],$u['username'],mb_substr($body,0,1000)]); redirect('index.php?msg=نظر شما ثبت شد.');
